import React from "react";
import {
    TheContent,
    TheSidebar,
    TheFooter,
    TheHeader,
} from "../containers/index";
import { useSelector } from "react-redux";
import { selectUser } from "../store/slices/userSlice";
import StudentRoutes from "./Student/studentRoutes";
import TeacherRoutes from "./Teacher/teacherRoutes";
import AdminRoutes from "./Admin/adminRoutes";
import AccountantRoutes from "./Accountant/teacherRoutes";
import StaffRoutes from "./Staff/teacherRoutes";
import StudentNavs from "./Student/sidebarNavs";
import TeacherNavs from "./Teacher/sidebarNavs";
import AdminNavs from "./Admin/sidebarNavs";
import AccountantNavs from "./Accountant/sidebarNavs";
import StaffNavs from "./Staff/sidebarNavs";

// Helper to recursively disable restricted sidebar items
const disableRestrictedItems = (items) => {
    return items.map((item) => {
        // Deep copy the item
        const newItem = { ...item };
        // Define Allowed Sections:
        // 1. Finance Section (checks route path)
        const isFinance = newItem.route && newItem.route.includes('/finance');
        // 2. The main "Reports" tab at the bottom
        const isReports = newItem.name === "Reports";
        // Check availability
        const isAllowed = isFinance || isReports;
        if (!isAllowed) {
            // Disable item: make it non-clickable and transparent
            newItem.attributes = {
                style: { pointerEvents: 'none', opacity: 0.5, cursor: 'not-allowed' },
                disabled: true
            };
            // IMPORTANT: Do NOT remove the 'to' prop entirely, just set it to current location or '#' 
            // removing it entirely corresponds to a 'title' or 'label' which might hide icons in CoreUI.
            newItem.to = '#';

            // Keep the icon property intact!
            // (newItem.icon is already preserved by the spread copy {...item})
        }
        // Recursively handle children
        if (newItem._children) {
            if (isAllowed) {
                // If parent is Finance, keep children active
            } else {
                // If parent is disabled, recursively disable children
                newItem._children = disableRestrictedItems(newItem._children);
            }
        }
        return newItem;
    });
};

const TheLayout = () => {
    const user = useSelector(selectUser);

    const getRoutes = () => {
        if (user) {
            switch (user.role) {
                case "student":
                    return StudentRoutes;
                case "teacher":
                    return TeacherRoutes;
                case "admin":
                    return AdminRoutes;
                case "accountant":
                    return AccountantRoutes;
                default:
                    return StudentRoutes;
            }
        }
        return [];
    };
    const getNavs = () => {
        if (user) {
            if (user.userID === 'accountant') {
                // Deep clone AdminNavs and filter
                const adminNavsCopy = JSON.parse(JSON.stringify(AdminNavs));

                // Manually restore icons if JSON.parse stripped functions/components (React elements)
                // Note: AdminNavs defines icons as React components (JSX), which JSON.stringify DESTROYS.
                // WE MUST NOT USE JSON.parse/stringify for React Components!

                // Fix: Use shallow copy or a better deep clone that preserves functions/JSX
                // Since AdminNavs is imported, we can map over it directly if we don't mutate deep properties of the original module.
                // Better approach: functional map without deep cloning with JSON.

                return disableRestrictedItems(AdminNavs); // We will update helper to not mutate original
            }
            switch (user.role) {
                case "student":
                    return StudentNavs;
                case "teacher":
                    return TeacherNavs;
                case "admin":
                    return AdminNavs;
                case "accountant":
                    return AccountantNavs;
                default:
                    // return StaffNavs;
                    return StudentNavs;

            }
        }
        return [];
    };

    return (
        <div className="c-app c-default-layout">
            <TheSidebar navs={getNavs()} />
            <div className="c-wrapper">
                <TheHeader routes={getRoutes()} />
                <div className="c-body">
                    <TheContent path={user?.role} routes={getRoutes()} />
                </div>
                <TheFooter />
            </div>
        </div>
    );
};

export default TheLayout;